import{z as B,x as d,o as E,c as A,q as l,j as s,D as t,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"轨道与扫描仪联机","description":"","frontmatter":{"title":"轨道与扫描仪联机","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/track-scanner-link.md","filePath":"litho/track-scanner-link.md","lastUpdated":1791413859000}'),p={name:"litho/track-scanner-link.md"};function D(c,a,h,m,u,P){const n=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=l('<h1 id="轨道与扫描仪联机" tabindex="-1">轨道与扫描仪联机 <a class="header-anchor" href="#轨道与扫描仪联机" aria-label="Permalink to &quot;轨道与扫描仪联机&quot;">​</a></h1><div class="epigraph"><p>涂胶–烘烤–显影在轨道，潜像在扫描仪。联机的是片、配方和时间，不是把两台机器写成一台。</p><footer>—— 对照 litho cluster（track + scanner）公开架构</footer></div><p><a href="/litho/hard-bake-uv-cure">上一课</a>停在显影后硬化。把整段工艺串起来，缺口是集群：哪一步在 track、哪一步在 scanner、片如何排队。主干 <a href="/litho/twinscan-dual-stage">Twinscan</a> 写过曝光产能；本课补轨道节拍与接口，不重写双工件台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描仪论场和剂量；轨道论模块占用：涂胶杯、热板、显影碗。节拍不匹配就堆片或饿曝光。PEB 延迟（曝光到 PEB 的时间）是化学放大胶的一等参数：酸在室温也会走，延迟散了 CD。把 PEB 延迟写成「剂量不稳」，会找错旋钮。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集群调度：曝光后尽快进 PEB 模块，延迟分布要进 SPC。接口：晶圆 ID、配方号、slot 对齐，避免涂了 A 胶去曝 B 程序。环境：轨道与扫描仪的温湿度、氨污染（胺会淬灭酸）要当一个 mill 的化学环境，不是两家设备商各管一段。</p>',7)),(E(),s(o,null,{default:t(()=>[i(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20COAT%5B%22%E6%B6%82%E8%83%B6%E8%BD%AF%E7%83%A4%22%5D%20--%3E%20EXP%5B%22%E6%89%AB%E6%8F%8F%E4%BB%AA%E6%9B%9D%E5%85%89%22%5D%0A%20%20EXP%20--%3E%20PEB%5B%22PEB%22%5D%0A%20%20PEB%20--%3E%20DEV%5B%22%E6%98%BE%E5%BD%B1%E5%86%B2%E6%B4%97%22%5D%0A%20%20DEV%20--%3E%20HB%5B%22%E7%A1%AC%E7%83%A4%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p><span class="marginnote">离线曝光（track 与 scanner 分开）在研发机台常见，PEB 延迟靠人跑秒表。量产集群把延迟收成受控分布。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><span class="marginnote">PEB 延迟翻译成大白话：曝光结束到进热板之间的等待时间。化学放大胶的酸从曝光那一刻就在扩散和被淬灭，等待不是免费的——每一秒都在悄悄改写潜像。</span></p><p>CAR 的酸在曝光后即存在，扩散与淬灭从这一刻起算。调度方差直接变 CDU。胺类 airborne base 在排队时中和酸，表现为「等得越久越欠曝」。</p><p><span class="marginnote">可以类比冲印照片：相纸曝光后化学反应在暗处仍继续，放久了亮暗边界自己糊开。集群调度的意义就是让每一片都在同样的等待窗口里进入下一站，把「运气」收成受控分布。</span></p><p><span class="marginnote">常见误区：CD 漂了先拧剂量。延迟分布散了同样漂 CD，而且方向固定朝欠曝——先调出调度日志看每片的延迟分布，再决定动不动剂量旋钮。</span></p>',6)),(E(),s(o,null,{default:t(()=>[i(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E6%9B%9D%E5%85%89%E5%AE%8C%E6%88%90%22%5D%20--%3E%20WAIT%5B%22%E6%8E%92%E9%98%9F%E7%AD%89%E5%BE%85%22%5D%0A%20%20WAIT%20--%3E%20DL%5B%22PEB%20%E5%BB%B6%E8%BF%9F%E6%8B%89%E9%95%BF%22%5D%0A%20%20DL%20--%3E%20DIFF%5B%22%E9%85%B8%E7%BB%A7%E7%BB%AD%E6%89%A9%E6%95%A3%22%5D%0A%20%20AMB%5B%22%E7%8E%AF%E5%A2%83%E8%83%BA%E6%B1%A1%E6%9F%93%22%5D%20--%3E%20NEU%5B%22%E4%B8%AD%E5%92%8C%E9%83%A8%E5%88%86%E9%85%B8%22%5D%0A%20%20NEU%20--%3E%20UND%5B%22%E6%AC%A0%E6%9B%9D%E6%96%B9%E5%90%91%E6%BC%82%E7%A7%BB%22%5D%0A%20%20DIFF%20--%3E%20CD%5B%22CD%20%E5%88%86%E5%B8%83%E5%8F%98%E5%AE%BD%22%5D%0A%20%20UND%20--%3E%20CD%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"边界",tabindex:"-1"},[r("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=e("p",null,"下一课热板均匀性：联机之后，仍可能是热板地图主导 CDU，而不是调度。",-1)),a[6]||(a[6]=e("h2",{id:"小结",tabindex:"-1"},[r("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=e("ul",null,[e("li",null,"集群把 PEB 延迟和环境化学收成受控量。"),e("li",null,"节拍匹配是产能，延迟匹配是 CD。"),e("li",null,"出处：litho cluster 通识；CAR 酸扩散课。")],-1))])}const k=B(p,[["render",D]]);export{C as __pageData,k as default};
